"""
Row-wise softmax in CUDA for H100.
Optimized for memory bandwidth on nvidia_h100_sxm.
"""
import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = """
#include <cuda.h>
#include <cuda_runtime.h>
#include <cmath>
#include <limits>

// Number of warps per block (matching Triton's num_warps=8)
#define NUM_WARPS 8
#define WARP_SIZE 32
#define BLOCK_THREADS (NUM_WARPS * WARP_SIZE)  // 256 threads

// Optimized warp reduction for max
__device__ __forceinline__ float warp_reduce_max(float val) {
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        val = fmaxf(val, __shfl_down_sync(0xffffffff, val, offset));
    }
    return val;
}

// Optimized warp reduction for sum
__device__ __forceinline__ float warp_reduce_sum(float val) {
    #pragma unroll
    for (int offset = 16; offset > 0; offset >>= 1) {
        val += __shfl_down_sync(0xffffffff, val, offset);
    }
    return val;
}

// Block-level reduction using shared memory
__device__ float block_reduce_max(float val, float* shared) {
    int lane = threadIdx.x % WARP_SIZE;
    int wid = threadIdx.x / WARP_SIZE;

    // Each warp performs partial reduction
    val = warp_reduce_max(val);

    // Write partial result to shared memory
    if (lane == 0) {
        shared[wid] = val;
    }
    __syncthreads();

    // First warp reads and reduces partial results
    if (wid == 0) {
        val = (lane < NUM_WARPS) ? shared[lane] : -INFINITY;
        val = warp_reduce_max(val);
    }
    __syncthreads();

    return val;
}

__device__ float block_reduce_sum(float val, float* shared) {
    int lane = threadIdx.x % WARP_SIZE;
    int wid = threadIdx.x / WARP_SIZE;

    val = warp_reduce_sum(val);

    if (lane == 0) {
        shared[wid] = val;
    }
    __syncthreads();

    if (wid == 0) {
        val = (lane < NUM_WARPS) ? shared[lane] : 0.0f;
        val = warp_reduce_sum(val);
    }
    __syncthreads();

    return val;
}

// Softmax kernel - persistent kernel pattern
// Each block handles multiple rows
template <int BLOCK_SIZE>
__global__ void softmax_kernel(
    half* __restrict__ output,
    const half* __restrict__ input,
    const int input_row_stride,
    const int output_row_stride,
    const int n_rows,
    const int n_cols
) {
    // Shared memory for reductions (NUM_WARPS elements)
    __shared__ float shared_data[NUM_WARPS];
    __shared__ float row_max_shared;
    __shared__ float row_sum_shared;

    const int row_start = blockIdx.x;
    const int row_step = gridDim.x;

    // Process rows in a persistent manner
    for (int row_idx = row_start; row_idx < n_rows; row_idx += row_step) {
        const half* row_input = input + row_idx * input_row_stride;
        half* row_output = output + row_idx * output_row_stride;

        // Phase 1: Find max
        float local_max = -INFINITY;

        #pragma unroll
        for (int col = threadIdx.x; col < BLOCK_SIZE; col += BLOCK_THREADS) {
            float val = (col < n_cols) ? __half2float(row_input[col]) : -INFINITY;
            local_max = fmaxf(local_max, val);
        }

        float row_max = block_reduce_max(local_max, shared_data);

        // Broadcast row_max to all threads
        if (threadIdx.x == 0) {
            row_max_shared = row_max;
        }
        __syncthreads();
        row_max = row_max_shared;

        // Phase 2: Compute exp(x - max) and sum
        float local_sum = 0.0f;

        // Load exp values and compute sum
        for (int col = threadIdx.x; col < BLOCK_SIZE; col += BLOCK_THREADS) {
            if (col < n_cols) {
                float val = __half2float(row_input[col]);
                float exp_val = expf(val - row_max);
                local_sum += exp_val;
            }
        }

        float row_sum = block_reduce_sum(local_sum, shared_data);

        // Broadcast row_sum to all threads
        if (threadIdx.x == 0) {
            row_sum_shared = row_sum;
        }
        __syncthreads();
        row_sum = row_sum_shared;

        // Phase 3: Write output
        float inv_sum = 1.0f / row_sum;

        for (int col = threadIdx.x; col < BLOCK_SIZE; col += BLOCK_THREADS) {
            if (col < n_cols) {
                float val = __half2float(row_input[col]);
                float exp_val = expf(val - row_max);
                row_output[col] = __float2half(exp_val * inv_sum);
            }
        }
    }
}

// Launch function
void launch_softmax_kernel(
    half* output,
    const half* input,
    int input_row_stride,
    int output_row_stride,
    int n_rows,
    int n_cols,
    cudaStream_t stream
) {
    int block_size = 1;
    while (block_size < n_cols) block_size *= 2;  // Next power of 2
    block_size = min(block_size, 4096);  // Cap at 4096

    int num_blocks = min(n_rows, 1024);  // Match Triton's n_programs
    int threads = BLOCK_THREADS;

    // Dispatch based on block size
    if (block_size <= 1024) {
        softmax_kernel<1024><<<num_blocks, threads, 0, stream>>>(
            output, input, input_row_stride, output_row_stride, n_rows, n_cols
        );
    } else if (block_size <= 2048) {
        softmax_kernel<2048><<<num_blocks, threads, 0, stream>>>(
            output, input, input_row_stride, output_row_stride, n_rows, n_cols
        );
    } else {
        softmax_kernel<4096><<<num_blocks, threads, 0, stream>>>(
            output, input, input_row_stride, output_row_stride, n_rows, n_cols
        );
    }
}
"""

cpp_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

void launch_softmax_kernel(
    half* output,
    const half* input,
    int input_row_stride,
    int output_row_stride,
    int n_rows,
    int n_cols,
    cudaStream_t stream
);

torch::Tensor softmax_cuda(torch::Tensor input) {
    TORCH_CHECK(input.dim() == 2, "Input must be 2D");
    TORCH_CHECK(input.scalar_type() == torch::kFloat16, "Input must be float16");

    auto output = torch::empty_like(input);
    int n_rows = input.size(0);
    int n_cols = input.size(1);

    launch_softmax_kernel(
        output.data_ptr<torch::Half>(),
        input.data_ptr<torch::Half>(),
        input.stride(0),
        output.stride(0),
        n_rows,
        n_cols,
        c10::cuda::getCurrentCUDAStream()
    );

    return output;
}
"""

# Load the extension
softmax_extension = load_inline(
    name='softmax_cuda_ext',
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=['softmax_cuda'],
    extra_cuda_cflags=['-O3', '-use_fast_math'],
    verbose=True
)


class ModelNew(nn.Module):
    def __init__(self):
        super().__init__()
        self.softmax_cuda = softmax_extension.softmax_cuda

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        # Ensure input is contiguous and on GPU
        if not x.is_contiguous():
            x = x.contiguous()
        if not x.is_cuda:
            x = x.cuda()

        # Convert to half if needed
        input_half = x if x.dtype == torch.float16 else x.half()

        return self.softmax_cuda(input_half)

