    __shared__ float shared[NUM_WARPS];
    int lane = threadIdx.x % WARP_SIZE;
    int wid = threadIdx.x / WARP_SIZE;

    // Each warp performs partial reduction
    val = warp_reduce_max(val);

    // Write partial result to shared memory
    if (lane == 0) {
        shared[wid] = val;
    }
    __syncthreads();

    // First warp reads and reduces partial results
    if (wid == 0) {
        val = (lane < NUM_WARPS) ? shared[lane] : -INFINITY;
        val = warp_reduce_max(val);
    }
    __syncthreads();

    return val;
}

__device__ float block_reduce_sum(float val) {
    __shared__ float shared[NUM_WARPS];
    int lane = threadIdx.x % WARP_SIZE;
    int wid = threadIdx.x / WARP_SIZE;

    val = warp_reduce_sum(val);

    if (lane == 0) {
        shared[wid] = val;
    }
    __syncthreads();

    if (wid == 0) {
        val = (lane < NUM_WARPS) ? shared[lane] : 0.0f;
        val = warp_reduce_sum(val);
    }
    __syncthreads();

    return val;
}

// Softmax kernel - persistent kernel pattern
// Each block handles multiple rows
__global__ void softmax_kernel(
    half* __restrict__ output,
    const half* __restrict__ input,
    const int input_row_stride,
    const int output_row_stride,
    const int n_rows,
    const int n_cols
) {
    const int row_start = blockIdx.x;
    const int row_step = gridDim.x;

    // Process rows in a persistent manner
    for (int row_idx = row_start; row_idx < n_rows; row_idx += row_step) {
        const half* row_input = input + row_idx * input_row_stride;
        half* row_output = output + row_idx * output_row_stride;

        // Phase 1: Find max
        float local_max = -INFINITY;

        for (int col = threadIdx.x; col < n_cols; col += BLOCK_THREADS) {
            float val = __half2float(row_input[col]);
            local_max = fmaxf(local_max, val);
        }

        float row_max = block_reduce_max(local_max);

        // Phase 2: Compute exp(x - max) and sum
        float local_sum = 0.0f;

        for (int col = threadIdx.x; col < n_cols; col += BLOCK_THREADS) {
            float val = __half2float(row_input[col]);
            float exp_val = expf(val - row_max);
            local_sum += exp_val;
        }

        float row_sum = block_reduce_sum(local_sum);

        // Phase 3: Write output
        float inv_sum = 1.0f / row_sum;

        for (int col = threadIdx.x; col < n_cols; col += BLOCK_THREADS) {
            float val = __half2float(row_input[col]);
            float exp_val = expf(val - row_max);
            row_output[col] = __float2half(exp_val * inv_sum);
        }
    }
}

torch::Tensor softmax_cuda(torch::Tensor input) {
    TORCH_CHECK(input.dim() == 2, "Input must be 2D");
    TORCH_CHECK(input.scalar_type() == torch::kFloat16, "Input must be float16");

    auto output = torch::empty_like(input);
    int n_rows = input.size(0);
    int n_cols = input.size(1);

    int num_blocks = std::min(n_rows, 1024);
    int threads = BLOCK_THREADS;

    // Get current CUDA stream
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();

    // Launch kernel
    softmax_kernel<<<num_blocks, threads, 0, stream>>>(
        reinterpret_cast<half*>(output.data_ptr<at::Half>()),
        reinterpret_cast<const half*>(input.data_ptr<at::Half>()),
        input.stride(0),
        output.stride(0),
